JOIN attributes a ON a.code = v.code
JOIN attribute_options o ON o.attribute_id = a.id AND o.value_code = v.value_code;

-- The joins above skip a value whose property or option doesn't exist; stop instead.
DO $$
BEGIN
    IF (SELECT count(*) FROM listing_attribute_values WHERE listing_id IN (SELECT listing_id FROM listing_media WHERE storage_key LIKE 'sample/%'))
           <> 1151
       OR (SELECT count(*) FROM listing_attribute_options WHERE listing_id IN (SELECT listing_id FROM listing_media WHERE storage_key LIKE 'sample/%'))
           <> 285 THEN
        RAISE EXCEPTION 'a sample property value names a property or option that does not exist';
    END IF;
END
$$;

-- Each listing goes into the subcategory for its kind (migration 0008).
UPDATE listings l
SET category_id = sub.id
FROM listing_attribute_values v
JOIN categories sub ON sub.replaces_option_id = v.value_option_id
WHERE v.listing_id = l.id AND sub.parent_id = l.category_id
  AND l.id IN (SELECT listing_id FROM listing_media WHERE storage_key LIKE 'sample/%');

-- Searchable property labels go into full-text search ("naftë" finds the diesel cars).
UPDATE listings SET search_extra = listing_search_extra(id)
WHERE id IN (SELECT listing_id FROM listing_media WHERE storage_key LIKE 'sample/%');

-- Each listing shows its seller's phone: the business's number, or the private seller's own.
INSERT INTO listing_contacts (listing_id, contact_name, phone_e164, show_phone)
SELECT l.id, coalesce(b.display_name, u.display_name), coalesce(b.public_phone, u.phone_e164), true
FROM listings l
LEFT JOIN businesses b ON b.id = l.seller_business_id
LEFT JOIN users u ON u.id = l.seller_user_id
WHERE l.id IN (SELECT listing_id FROM listing_media WHERE storage_key LIKE 'sample/%');

-- Points on the map, approximate like real private sellers' ones: up to 1.5 km from the town's
-- centre, in a direction and at a distance taken from the listing's id, so they stay put. Where
-- the centre is on the shore, they spread less far around a spot inland, so none land in water.
WITH inland (slug, latitude, longitude, km) AS (
    VALUES ('durres', 41.3260, 19.4540, 1.0),
           ('vlore', 40.4694, 19.4861, 1.0),
           ('sarande', 39.8800, 20.0100, 0.5),
           ('pogradec', 40.8963, 20.6568, 0.5)
), points AS (
    SELECT l.id, coalesce(i.latitude, loc.latitude) AS lat, coalesce(i.longitude, loc.longitude) AS lng,
           coalesce(i.km, 1.5) * sqrt(('x' || substr(md5(l.id::text), 1, 8))::bit(32)::bigint / 4294967295.0) AS km,
           2 * pi() * ('x' || substr(md5(l.id::text), 9, 8))::bit(32)::bigint / 4294967295.0 AS angle
    FROM listings l
    JOIN locations loc ON loc.id = l.location_id
    LEFT JOIN inland i ON i.slug = loc.slug
    WHERE l.id IN (SELECT listing_id FROM listing_media WHERE storage_key LIKE 'sample/%')
)
UPDATE listings l
SET latitude = round((p.lat + p.km * cos(p.angle) / 111.32)::numeric, 6),
    longitude = round((p.lng + p.km * sin(p.angle) / (111.32 * cos(radians(p.lat))))::numeric, 6)
FROM points p
WHERE p.id = l.id;

-- Search fixes typos from the words listings use (migration 0016), a list the app rebuilds every
-- quarter of an hour; rebuilt here, it has these listings' words at once.
REFRESH MATERIALIZED VIEW search_words;

COMMIT;

